-- Venue Live Guest "Lamaran Galeri Seni". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara lamaran), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'lamaran', 'Lamaran Galeri Seni', 'lamaran', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 156, 'center 38%',
  $t${"name":"Lamaran Galeri Seni","orn":"diamond","ui":{"ivory":"#FAF5FC","white":"#FFFFFF","soft":"#EBDDF5","soft2":"#C9A6E0","accent":"#9B6BC4","deep":"#5A3A7E","ink":"#4A2F66","mute":"#8F7AA6","line":"#E6D8F0","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FDFAFF","ink":"#4A2F66","accent":"#9B6BC4","gold":"#C9A24A","leaf":"#EBDDF5","hbg":"rgba(250,245,252,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(74,47,102,.9)","acc":"#F2D27A","on":"#4A2F66"},"scr":{"wine":"#5A3A7E","veil":"250,245,252"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'lamaran');
